head.b:skin:
:root{--bg:#f7f5f0;--card:#fff;--ink:#1c1b19;--mute:#6b675f;--line:#e4e0d6;--acc:#0f5f58;--acc-ink:#fff;--ok:#1f7a45;--bad:#b3261e;--r:14px}
:root[data-theme=dark]{--bg:#151513;--card:#1f1f1c;--ink:#f1eee6;--mute:#a7a296;--line:#33322d;--acc:#5fc7bb;--acc-ink:#0d1b19;--ok:#6fd08f;--bad:#ff8a80}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:400 17px/1.8 'Noto Sans Arabic',system-ui,sans-serif}
a{color:var(--acc)}
.wrap{max-width:1040px;margin:0 auto;padding:0 20px}
.skip{position:absolute;top:0;inset-inline-start:0;transform:translateY(-200%);background:var(--card);padding:8px 12px;z-index:9}.skip:focus{transform:none}
.top{border-bottom:1px solid var(--line);background:var(--bg)}
.bar{display:flex;align-items:center;gap:16px;min-height:64px;flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:10px;color:var(--ink);text-decoration:none;font-weight:700;font-size:20px}
.brand svg{width:32px;height:32px}
.nav{display:flex;gap:20px;margin-inline-start:auto;flex-wrap:wrap}
.nav a{color:var(--ink);text-decoration:none;font-size:15px}
.nav a:hover{color:var(--acc)}
button,.btn{font:inherit;cursor:pointer}
.btn{display:inline-block;background:var(--acc);color:var(--acc-ink);border:0;border-radius:10px;padding:10px 20px;text-decoration:none;font-weight:600}
.btn.alt{background:transparent;color:var(--ink);border:1px solid var(--line)}
.btn-quiet{background:none;border:1px solid var(--line);border-radius:10px;color:var(--mute);padding:6px 14px;font-size:14px}
:focus-visible{outline:2px solid var(--acc);outline-offset:2px}
.hero{padding:56px 0 24px}
.eyebrow{color:var(--mute);font-size:14px;margin:0 0 8px}
.hero h1{font-size:clamp(30px,5vw,48px);line-height:1.3;margin:0 0 16px;font-weight:700}
.lede{max-width:620px;color:var(--mute);margin:0 0 24px}
.cta{display:flex;gap:12px;flex-wrap:wrap}
.sec{padding:32px 0}
.sec h2{font-size:26px;margin:0 0 16px}
.picker{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}
.picker button{background:var(--card);border:1px solid var(--line);border-radius:999px;padding:8px 18px;color:var(--ink)}
.picker button[aria-pressed=true]{background:var(--acc);color:var(--acc-ink);border-color:var(--acc)}
.topics{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px;list-style:none;margin:0;padding:0}
.topics a{display:block;height:100%;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px;text-decoration:none;color:var(--ink)}
.topics b{display:block}.topics span{color:var(--mute);font-size:14px}
.content{padding:24px 0 48px}
.content .post{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:20px 24px;margin:0 0 16px}
.content .post h2,.content .post h1{margin:0 0 8px;font-size:24px}
.content .post h2 a{color:var(--ink);text-decoration:none}
.meta{color:var(--mute);font-size:14px;margin:0 0 8px}
.pager{display:flex;justify-content:space-between;gap:12px}
.foot{border-top:1px solid var(--line);padding:32px 0;color:var(--mute);font-size:15px}
.foot ul{list-style:none;margin:0;padding:0}.foot a{color:var(--mute)}
.foot-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:24px;margin-bottom:24px}
.foot h4{margin:0 0 8px;color:var(--ink)}
.foot-end{display:flex;justify-content:space-between;align-items:center;gap:12px}
.note{color:var(--mute);font-size:14px}
/* games */
.bsr-game{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:20px;min-height:260px}
.bsr-game h3{margin:0 0 4px;font-size:22px}
.g-sub{color:var(--mute);margin:0 0 16px}
.g-bar{display:flex;justify-content:space-between;color:var(--mute);font-size:14px;margin:0 0 12px}
.g-prog{height:6px;background:var(--line);border-radius:3px;margin:0 0 16px;overflow:hidden}.g-prog i{display:block;height:100%;background:var(--acc)}
.g-q{font-size:20px;font-weight:600;margin:0 0 16px}
.g-opts{display:grid;gap:10px}
.g-opt{text-align:start;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:12px 16px;color:var(--ink)}
.g-opt:hover:not(:disabled){border-color:var(--acc)}
.g-opt.ok{border-color:var(--ok);background:color-mix(in srgb,var(--ok) 14%,var(--card))}
.g-opt.bad{border-color:var(--bad);background:color-mix(in srgb,var(--bad) 14%,var(--card))}
.g-fb{margin:16px 0 0;padding:12px 16px;border-radius:10px;background:var(--bg);border:1px solid var(--line)}
.g-fb strong.ok{color:var(--ok)}.g-fb strong.bad{color:var(--bad)}
.g-act{margin-top:16px;display:flex;gap:10px;flex-wrap:wrap}
.g-end{text-align:center;padding:16px 0}
.g-score{font-size:44px;font-weight:700;margin:0}
.g-ord{list-style:none;margin:0 0 12px;padding:0;display:grid;gap:8px}
.g-ord li{background:var(--bg);border:1px dashed var(--line);border-radius:10px;padding:10px 14px;min-height:46px}
.g-ord li.fill{border-style:solid}
.g-word{font-size:34px;letter-spacing:.2em;text-align:center;margin:8px 0 16px;direction:rtl}
.g-in{font:inherit;padding:10px 14px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);width:min(100%,240px)}
.g-mem{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.g-card{min-height:72px;border:1px solid var(--line);border-radius:10px;background:var(--acc);color:var(--acc-ink);font-size:16px;padding:6px}
.g-card.up{background:var(--bg);color:var(--ink)}
.g-card.done{background:color-mix(in srgb,var(--ok) 18%,var(--card));color:var(--ink);border-color:var(--ok)}
@media (max-width:560px){.g-mem{grid-template-columns:repeat(3,1fr)}}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}
/* مرحلة A: هيدر وبحث ولغة */
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.find{display:flex;flex:1 1 220px;max-width:360px;min-width:0;gap:6px}
.find input{flex:1;min-width:0;width:100%;font:inherit;padding:8px 12px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--ink)}
.find button{font:inherit;padding:8px 14px;border:0;border-radius:10px;background:var(--acc);color:var(--acc-ink);min-height:44px}
.bar-end{display:flex;gap:8px;margin-inline-start:auto}
.btn-quiet{min-height:44px}
.nav{margin-inline-start:0;flex:1 1 100%;order:3;overflow-x:auto;white-space:nowrap;gap:20px;padding-bottom:8px}
.nav a{display:inline-flex;align-items:center;min-height:44px}
.verify{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:20px}
.verify h2{margin:0 0 6px}.verify p{margin:0;color:var(--mute);max-width:560px}
.sec-h{font-size:24px;margin:0 0 16px}
html[dir=ltr] body{font-family:'Inter','Noto Sans Arabic',system-ui,sans-serif}
@media (min-width:900px){.nav{flex:0 1 auto;order:0;margin-inline-start:12px;overflow:visible;padding:0}.bar-end{margin-inline-start:0}}

