(function(){
'use strict';
var DICT={"ar":{"brand":"BASIRA | بصيرة","nav.games":"الألعاب","nav.topics":"المعرفة","nav.articles":"المقالات","nav.verify":"كيف نتحقق","search.ph":"ابحث في المقالات","search.btn":"بحث","search.label":"ابحث في الموقع","lang.switch":"English","theme.dark":"الوضع الداكن","theme.light":"الوضع الفاتح","hero.eyebrow":"Think. Discover. Play. · فكّر. اكتشف. العب.","hero.title":"اعرف أكثر، ثم تحدَّ نفسك","hero.lede":"معلومات موثّقة بالمصادر وألعاب ذهنية بالعربية. تلعب فوراً بلا تسجيل، وتُحفظ نتائجك على جهازك فقط.","hero.cta":"ابدأ اللعب","hero.cta2":"تصفّح المعرفة","games.title":"الألعاب","topics.title":"أقسام المعرفة","latest.title":"أحدث المقالات","verify.title":"كيف نتحقق","verify.text":"كل رقم أو تاريخ في مقالاتنا له مصدر مذكور، وأسئلة الألعاب تُراجع قبل ظهورها ولا تُولَّد أثناء اللعب.","verify.link":"اقرأ منهجنا","foot.note":"معلومات موثّقة وألعاب ذهنية بالعربية، تعمل بلا تسجيل.","foot.topics":"أقسام المعرفة","foot.about":"عن الموقع","foot.pending":"الصفحات التعريفية قيد الإعداد","lang.note":"محتوى الأسئلة والمقالات الإنجليزية قيد المراجعة، لذلك تظهر الأسئلة بالعربية الآن.","noscript":"تحتاج الألعاب إلى تفعيل JavaScript.","t.العلوم":"العلوم","t.التاريخ والحضارات":"التاريخ والحضارات","t.الجغرافيا والدول":"الجغرافيا والدول","t.التكنولوجيا":"التكنولوجيا","t.الثقافة العامة":"الثقافة العامة","t.الرياضيات والمنطق":"الرياضيات والمنطق","t.اللغة والأدب":"اللغة والأدب","t.الفضاء والفلك":"الفضاء والفلك","g.mcq.name":"اختبارات متعددة الخيارات","g.mcq.desc":"أربع إجابات وتفسير بعد كل سؤال","g.truefalse.name":"صح أم خطأ","g.truefalse.desc":"جمل سريعة تختبر دقة معلوماتك","g.order.name":"ترتيب الأحداث","g.order.desc":"رتّب وقائع بالتسلسل الصحيح","g.memory.name":"لعبة الذاكرة","g.memory.desc":"اكتشف الأزواج بأقل عدد من المحاولات","g.word.name":"خمّن الكلمة","g.word.desc":"كلمة مخفية وتلميحات تساعدك"},"en":{"brand":"BASIRA | بصيرة","nav.games":"Games","nav.topics":"Knowledge","nav.articles":"Articles","nav.verify":"How we verify","search.ph":"Search articles","search.btn":"Search","search.label":"Search the site","lang.switch":"العربية","theme.dark":"Dark mode","theme.light":"Light mode","hero.eyebrow":"Think. Discover. Play.","hero.title":"Learn something, then challenge yourself","hero.lede":"Sourced knowledge and brain games in Arabic and English. Play right away with no sign-up; your results stay on your device.","hero.cta":"Start playing","hero.cta2":"Browse knowledge","games.title":"Games","topics.title":"Knowledge sections","latest.title":"Latest articles","verify.title":"How we verify","verify.text":"Every figure and date in our articles has a cited source, and game questions are reviewed before they appear, never generated while you play.","verify.link":"Read our method","foot.note":"Sourced knowledge and brain games, no sign-up needed.","foot.topics":"Knowledge sections","foot.about":"About","foot.pending":"Info pages are being prepared","lang.note":"English questions and articles are still under review, so questions are shown in Arabic for now.","noscript":"Games need JavaScript enabled.","t.العلوم":"Science","t.التاريخ والحضارات":"History & Civilizations","t.الجغرافيا والدول":"Geography & Countries","t.التكنولوجيا":"Technology","t.الثقافة العامة":"General Knowledge","t.الرياضيات والمنطق":"Math & Logic","t.اللغة والأدب":"Language & Literature","t.الفضاء والفلك":"Space & Astronomy","g.mcq.name":"Multiple choice","g.mcq.desc":"Four answers, with an explanation after each","g.truefalse.name":"True or false","g.truefalse.desc":"Quick statements that test your accuracy","g.order.name":"Timeline order","g.order.desc":"Put events in the right order","g.memory.name":"Memory","g.memory.desc":"Find the pairs in as few tries as possible","g.word.name":"Guess the word","g.word.desc":"A hidden word and hints that help"}};
var KEY='basira.lang';
function getLang(){
  var m=/[?&]lang=(en|ar)/.exec(location.search);
  if(m)return m[1];
  try{var s=localStorage.getItem(KEY);if(s==='en'||s==='ar')return s;}catch(e){}
  return 'ar';
}
var lang=getLang();
function t(k){var d=DICT[lang]||DICT.ar;return d[k]!=null?d[k]:(DICT.ar[k]!=null?DICT.ar[k]:k);}
function apply(){
  var d=document.documentElement;
  d.setAttribute('lang',lang);d.setAttribute('dir',lang==='en'?'ltr':'rtl');
  [].forEach.call(document.querySelectorAll('[data-i]'),function(n){n.textContent=t(n.getAttribute('data-i'));});
  [].forEach.call(document.querySelectorAll('[data-ip]'),function(n){n.setAttribute('placeholder',t(n.getAttribute('data-ip')));});
  [].forEach.call(document.querySelectorAll('.js-lang'),function(n){n.textContent=t('lang.switch');});
  var note=document.getElementById('lang-note');if(note)note.hidden=(lang!=='en');
  var tb=document.querySelectorAll('.js-theme');
  [].forEach.call(tb,function(b){b.textContent=t(d.getAttribute('data-theme')==='dark'?'theme.light':'theme.dark');});
}
function set(l){
  lang=l;try{localStorage.setItem(KEY,l);}catch(e){}
  apply();
  try{document.dispatchEvent(new CustomEvent('basira:lang',{detail:l}));}catch(e){}
}
window.BSR=window.BSR||{};
window.BSR.t=t;window.BSR.lang=function(){return lang;};window.BSR.setLang=set;window.BSR.applyI18n=apply;
function init(){
  [].forEach.call(document.querySelectorAll('.js-lang'),function(b){b.addEventListener('click',function(){set(lang==='en'?'ar':'en');});});
  apply();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();

(function(){
'use strict';
